"""Login HTTP: server-side session cookie and /api/me."""

from __future__ import annotations

from typing import NoReturn

from fastapi import APIRouter, HTTPException, Request, Response
from fastapi.responses import JSONResponse
from pydantic import BaseModel

from endo_label.coordination import (
    Account,
    AssignmentNotFound,
    LabelWriteForbidden,
    VersionConflict,
    account_for_session,
    assert_label_writer,
    authenticate,
    authorize_label_write,
    clip_version,
    create_session,
    db_path,
    delete_session,
)

SESSION_COOKIE = "session_id"

router = APIRouter()

_PUBLIC_API = frozenset({"/api/health", "/api/auth/login", "/api/auth/logout"})


class LoginBody(BaseModel):
    username: str
    password: str


def _me(account: Account) -> dict:
    return {
        "username": account.username,
        "roles": {
            "admin": account.admin,
            "reviewer": account.reviewer,
            "annotator": account.annotator,
        },
    }


def install_auth(app) -> None:
    @app.middleware("http")
    async def require_account(request: Request, call_next):
        path = request.url.path
        if (
            request.method == "OPTIONS"
            or not path.startswith("/api/")
            or path in _PUBLIC_API
        ):
            return await call_next(request)
        settings = request.app.state.settings
        token = request.cookies.get(SESSION_COOKIE)
        account = account_for_session(db_path(settings), token) if token else None
        if account is None or account.disabled:
            return JSONResponse({"detail": "Not authenticated"}, status_code=401)
        request.state.account = account
        return await call_next(request)


def require_admin(request: Request) -> Account:
    account: Account = request.state.account
    if not account.admin:
        raise HTTPException(status_code=403, detail="Admin only")
    return account


def _label_write_http(exc: Exception) -> NoReturn:
    if isinstance(exc, AssignmentNotFound):
        raise HTTPException(status_code=404, detail="Not Found") from None
    if isinstance(exc, LabelWriteForbidden):
        raise HTTPException(status_code=403, detail="Forbidden") from None
    if isinstance(exc, VersionConflict):
        raise HTTPException(status_code=409, detail="Version conflict") from None
    raise exc


def require_label_assignee(request: Request, clip_id: str, task_type: str) -> None:
    account: Account = request.state.account
    try:
        assert_label_writer(
            db_path(request.app.state.settings),
            account_id=account.id,
            clip_id=clip_id,
            task_type=task_type,
        )
    except Exception as exc:
        _label_write_http(exc)


def require_label_write(
    request: Request,
    clip_id: str,
    task_type: str,
    version: int | None = None,
) -> int:
    account: Account = request.state.account
    try:
        return authorize_label_write(
            db_path(request.app.state.settings),
            account_id=account.id,
            clip_id=clip_id,
            task_type=task_type,
            version=version,
        )
    except Exception as exc:
        _label_write_http(exc)


def with_clip_version(request: Request, clip_id: str, doc: dict) -> dict:
    out = dict(doc)
    out["version"] = clip_version(db_path(request.app.state.settings), clip_id)
    return out


def with_new_version(doc: dict, version: int) -> dict:
    out = dict(doc)
    out["version"] = version
    return out


@router.post("/api/auth/login")
def login(body: LoginBody, response: Response, request: Request) -> dict:
    settings = request.app.state.settings
    path = db_path(settings)
    account = authenticate(path, body.username, body.password)
    if account is None:
        raise HTTPException(status_code=401, detail="Not authenticated")
    token = create_session(path, account.id)
    response.set_cookie(
        key=SESSION_COOKIE,
        value=token,
        httponly=True,
        samesite="lax",
        secure=settings.session_cookie_secure,
        path="/",
    )
    return _me(account)


@router.post("/api/auth/logout")
def logout(request: Request, response: Response) -> dict:
    token = request.cookies.get(SESSION_COOKIE)
    if token:
        delete_session(db_path(request.app.state.settings), token)
    response.delete_cookie(SESSION_COOKIE, path="/")
    return {"ok": True}


@router.get("/api/me")
def me(request: Request) -> dict:
    return _me(request.state.account)

import { useState, type FormEvent } from "react";
import useSWR, { mutate } from "swr";
import { getJson, sendJson } from "./api";
import { Button } from "./components/ui/button";
import { Input } from "./components/ui/input";

type AssignmentItem = {
  clip_id: string;
  task_type: string;
  state: string;
  assignee: string | null;
  reviewer: string | null;
  note: string | null;
  reviewed_by: string | null;
  reviewed_at: string | null;
  delivered_at: string | null;
  version: number;
};

type ItemsResponse = { items: AssignmentItem[] };

function ItemRow({
  item,
  action,
}: {
  item: AssignmentItem;
  action: "assign" | "reassign";
}) {
  const [username, setUsername] = useState("");
  const [error, setError] = useState<string | null>(null);

  async function onSubmit(event: FormEvent) {
    event.preventDefault();
    setError(null);
    try {
      await sendJson(
        `/api/items/${encodeURIComponent(item.clip_id)}/${encodeURIComponent(item.task_type)}/${action}`,
        "POST",
        { assignee: username },
      );
      setUsername("");
      await mutate("/api/items");
    } catch (err) {
      setError(err instanceof Error ? err.message : "Could not update Assignment");
    }
  }

  return (
    <li className="flex flex-col gap-2 border-b border-border py-3">
      <div className="text-sm">
        <span className="font-medium">{item.clip_id}</span>
        <span className="text-muted-foreground"> · {item.task_type}</span>
        {item.assignee ? (
          <span className="text-muted-foreground"> · {item.assignee}</span>
        ) : null}
      </div>
      <form className="flex gap-2" onSubmit={onSubmit}>
        <Input
          aria-label={`Username for ${item.clip_id} ${item.task_type}`}
          value={username}
          onChange={(event) => setUsername(event.target.value)}
        />
        <Button type="submit" size="sm">
          {action === "assign" ? "Assign" : "Reassign"}
        </Button>
      </form>
      {error ? <p role="alert">{error}</p> : null}
    </li>
  );
}

export function AssignmentsBoard() {
  const { data, error } = useSWR("/api/items", getJson<ItemsResponse>);
  if (!data && !error) {
    return <p className="p-6">Loading…</p>;
  }
  if (error || !data) {
    return (
      <main className="p-6">
        <h1 className="text-xl font-semibold">Assignments</h1>
        <p role="alert">{error instanceof Error ? error.message : "Could not load Assignments"}</p>
      </main>
    );
  }
  const unassigned = data.items.filter((item) => item.state === "Unassigned");
  const labeling = data.items.filter((item) => item.state === "Labeling");
  return (
    <main className="h-full overflow-auto p-6">
      <h1 className="text-xl font-semibold">Assignments</h1>
      <div className="mt-4 grid grid-cols-2 gap-6">
        <section>
          <h2 className="mb-2 text-sm font-medium">Unassigned</h2>
          <ul>
            {unassigned.map((item) => (
              <ItemRow key={`${item.clip_id}:${item.task_type}`} item={item} action="assign" />
            ))}
          </ul>
        </section>
        <section>
          <h2 className="mb-2 text-sm font-medium">Labeling</h2>
          <ul>
            {labeling.map((item) => (
              <ItemRow key={`${item.clip_id}:${item.task_type}`} item={item} action="reassign" />
            ))}
          </ul>
        </section>
      </div>
    </main>
  );
}

